public class BootSequenceTrackerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("class loading runs the static parts only",
                "[static-field, static-block]", BootSequenceTracker.events().toString());
        check("no objects built yet", 0, BootSequenceTracker.instanceCount());
        check("the static field kept what note() returned", "static-field", BootSequenceTracker.label());

        BootSequenceTracker first = new BootSequenceTracker();
        check("building an object runs field, block, constructor",
                "[static-field, static-block, instance-field, instance-block, constructor]",
                BootSequenceTracker.events().toString());
        check("the instance field kept what note() returned", "instance-field", first.id());

        new BootSequenceTracker();
        check("the static parts do not run again",
                "[static-field, static-block, instance-field, instance-block, constructor, "
                        + "instance-field, instance-block, constructor]",
                BootSequenceTracker.events().toString());
        check("both objects were counted", 2, BootSequenceTracker.instanceCount());
        check("events() hands back a copy, not the live list", 8,
                copyThenGrow());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static int copyThenGrow() {
        BootSequenceTracker.events().add("tampered");
        return BootSequenceTracker.events().size();
    }
}

