import java.util.ArrayList;
import java.util.List;

/**
 * TASK: Make Java's initialisation order observable. Add the missing
 * initialisers so that every step appends its name to EVENTS in the order
 * the JVM actually runs them.
 *
 * Order to produce:
 *   loading the class runs  "static-field" then "static-block" -- ONCE
 *   each new object runs    "instance-field", "instance-block", "constructor"
 *
 * So after the class is loaded and two objects have been built, events() is
 *   [static-field, static-block,
 *    instance-field, instance-block, constructor,
 *    instance-field, instance-block, constructor]
 *
 * EVENTS, note(...) and events() are provided. Keep EVENTS declared FIRST:
 * a static field initialiser that runs before the list exists would blow up
 * with a NullPointerException.
 *
 * Rules:
 *   - label() returns the value the static field was initialised to
 *     ("static-field"), and id() returns the instance field's value
 *     ("instance-field") -- note(...) hands that text back to you
 *   - instanceCount() reports how many objects have been constructed
 */
public class BootSequenceTracker {

    private static final List<String> EVENTS = new ArrayList<>();

    private static final String LABEL = note("static-field");

    static {
        note("static-block");
    }

    private final String id = note("instance-field");

    {
        note("instance-block");
    }

    private static int built = 0;

    public BootSequenceTracker() {
        note("constructor");
        built++;
    }

    private static String note(String event) {
        EVENTS.add(event);
        return event;
    }

    public static List<String> events() {
        return new ArrayList<>(EVENTS);
    }

    public static String label() {
        return LABEL;
    }

    public String id() {
        return id;
    }

    public static int instanceCount() {
        return built;
    }
}
